import React, {useEffect} from 'react';
import { ApolloProvider } from '@apollo/client';
import { IntlProvider } from 'react-intl';
import './index.css';
import { ApplyGlobalStyles, Spinner } from '@databricks/design-system';
import '@databricks/design-system/dist/index.css';
import '@databricks/design-system/dist/index-dark.css';
import App from './experiment-tracking/components/App';
import { Provider } from 'react-redux';
import store from './store';
import { useI18nInit } from './i18n/I18nUtils';
import { DesignSystemContainer } from './common/components/DesignSystemContainer';
import { ConfigProvider } from 'antd';
import { LegacySkeleton } from '@databricks/design-system';
import { shouldUsePathRouting } from './common/utils/FeatureUtils';
// eslint-disable-next-line no-useless-rename
import { MlflowRouter as MlflowRouter } from './MlflowRouter';
import { useMLflowDarkTheme } from './common/hooks/useMLflowDarkTheme';

export function MLFlowRoot() {
  const [userDetails, setUserDetails] = React.useState<any>({});

  const shouldSetUserInfo = (userDetails: any) => {
    let userDetailsInLocalStorage: any = localStorage.getItem('userInfo');
    if (!userDetailsInLocalStorage) {
      return true;
    }
    userDetailsInLocalStorage = JSON.parse(userDetailsInLocalStorage);
    if (userDetailsInLocalStorage?.email && userDetailsInLocalStorage?.email === userDetails.email) {
      return false;
    }
    return true
  }

  const setUserInfoIfNotPresent = (userDetails: any) => {
      localStorage.setItem('userInfo', JSON.stringify(userDetails));
  }

  useEffect(() => {
    window.addEventListener('message', (ev: MessageEvent<{ type: string; message: string }>) => {
      if (ev?.data?.type === 'userInfo') {
        const userDetails = ev?.data?.message
        if (userDetails) {
          if (shouldSetUserInfo(userDetails)) {
            setUserInfoIfNotPresent(userDetails);
            window.location.reload();
          }
          setUserDetails(userDetails);
        }
      }
    });
  }, []);

  // eslint-disable-next-line react-hooks/rules-of-hooks
  const i18n = useI18nInit();

  // eslint-disable-next-line react-hooks/rules-of-hooks
  const [isDarkTheme, setIsDarkTheme, MlflowThemeGlobalStyles] = useMLflowDarkTheme();

  if (!i18n) {
    return (
      <DesignSystemContainer>
        <LegacySkeleton />
      </DesignSystemContainer>
    );
  }

  const { locale, messages } = i18n;

  return (
      userDetails?.email ? <IntlProvider locale={locale} messages={messages}>
        <Provider store={store}>
          <DesignSystemContainer isDarkTheme={isDarkTheme}>
            <ApplyGlobalStyles/>
            <MlflowThemeGlobalStyles/>
            <ConfigProvider prefixCls="ant">
              {shouldUsePathRouting() ? (
                  <MlflowRouter isDarkTheme={isDarkTheme} setIsDarkTheme={setIsDarkTheme}/>
              ) :
                  <App isDarkTheme={isDarkTheme} setIsDarkTheme={setIsDarkTheme}/>
              }
            </ConfigProvider>
          </DesignSystemContainer>
        </Provider>
      </IntlProvider> : <div css={{height: '100%', display: 'flex', justifyContent: 'center', alignItems: 'center'}}>
        <Spinner size="large"/>
      </div>)
}
